 {Host h;configure(h);assert(h.scope.prepare()==Result::ok);h.own=false;int before=h.writes;assert(h.scope.release(false)==Result::ok);assert(h.writes==before&&h.roots.empty());assert(h.sound.volume==0);}
 {Host h;configure(h);assert(h.scope.prepare()==Result::ok);h.mixer=9;h.frame_count=56;h.corrupt=true;assert(h.scope.restore()==Result::stale);h.corrupt=false;h.frame_count=59;assert(h.scope.restore()==Result::ok);assert(h.frame.value==9&&h.status.value==49);assert(h.scope.verify_source_restored()==Result::ok);assert(h.scope.release(true)==Result::ok);}
 {Host h;configure(h);assert(h.scope.prepare()==Result::ok);h.brain.reference=nullptr;h.no_barrier=true;assert(h.scope.restore()==Result::failed);assert(!h.scope.restoration_verified());assert(h.scope.release(false)==Result::ok);}
 {Host h;configure(h,false);assert(h.scope.prepare()==Result::ok);assert(h.scope.restore()==Result::ok);h.logical_ready=false;h.sound.playing=true;assert(h.scope.verify_source_restored()==Result::failed);assert(!h.scope.restoration_verified());assert(h.scope.release(false)==Result::ok);}
 {Host h;configure(h);assert(h.scope.prepare()==Result::ok);assert(h.scope.restore()==Result::ok);h.sound.playing=true;assert(h.scope.verify_source_restored()==Result::failed);assert(h.scope.release(false)==Result::ok);}
 {Host h;configure(h);h.frame.value=99;assert(h.scope.prepare()==Result::ok);assert(h.scope.restore()==Result::ok);assert(h.frame.value==7);assert(h.scope.verify_source_restored()==Result::ok);assert(h.scope.release(true)==Result::ok);}
 {Host h;host=&h;h.frame.value=99;h.sound.clip=&h.clip;Owner o{&h,&h.clip,&h.object,&h.transform,&h.brain,&h.sound,nullptr,2};assert(h.scope.configure(api(),&h,o)==Result::ok);assert(h.scope.capture()==Result::unsupported);assert(!h.restores&&!h.writes&&h.sound.volume==.6f);assert(h.scope.release(false)==Result::ok);assert(h.roots.empty());}
 {Host h;configure(h);assert(!h.scope.permit_brain_update(&h.brain));assert(!h.scope.consume_render_grant());assert(h.scope.reset()==Result::ok);assert(h.scope.grant(0)==Result::ok);assert(h.scope.permit_brain_update(&h.brain));assert(h.scope.permit_brain_update(&h.brain));uint64_t tick=999;assert(h.scope.render_tick(tick)&&tick==0);assert(h.scope.consume_render_grant());assert(!h.scope.consume_render_grant());assert(h.scope.hold()==Result::ok);assert(!h.scope.consume_render_grant());assert(!h.scope.permit_brain_update(&h.brain));assert(h.scope.grant(1)==Result::ok);assert(h.scope.consume_render_grant());assert(!h.scope.consume_render_grant());assert(h.scope.grant(2)==Result::ok);h.scope.revoke_grants();assert(!h.scope.permit_brain_update(&h.brain));assert(!h.scope.consume_render_grant());assert(!h.scope.arm_render_retry(1));assert(h.scope.arm_render_retry(2));assert(!h.scope.permit_brain_update(&h.brain));assert(h.scope.consume_render_grant());assert(!h.scope.arm_render_retry(2));assert(h.scope.grant(3)==Result::ok);h.own=false;h.scope.revoke_grants();assert(!h.scope.consume_render_grant());assert(!h.scope.frame_granted()&&!h.scope.permit_brain_update(&h.brain));assert(h.scope.release(false)==Result::ok);}
 {Host h;h.sound.playing=true;h.sound.paused=false;h.logical_playing=true;h.logical_paused=false;configure(h,false);assert(h.scope.prepare()==Result::ok&&!h.sound.playing&&h.sound.paused);assert(h.scope.restore()==Result::ok);assert(h.scope.verify_source_restored()==Result::ok&&h.logical_calls>0);assert(!h.sound.playing&&!h.sound.paused&&!h.native_plays);assert(h.scope.release(true)==Result::ok);}
